const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    // Cairns, Australia is approx. -16.92, 145.77. 100km east is approx. 1 degree of longitude.
    const location = ee.Geometry.Point([146.77, -16.92]);

    const targetStartDate = '2022-03-01';
    const targetEndDate = '2022-03-31';
    const baselineStartDate = '2003-01-01';
    const baselineEndDate = '2014-12-31';

    // 2. Data Acquisition
    const sstCollection = ee.ImageCollection('NOAA/CDR/OISST/V2.1').select('sst');

    const baselineColl = sstCollection.filterDate(baselineStartDate, baselineEndDate);
    const targetColl = sstCollection.filterDate(targetStartDate, targetEndDate);

    // 3. Data Availability Check
    const baselineSize = baselineColl.size().getInfo();
    const targetSize = targetColl.size().getInfo();

    if (baselineSize === 0 || targetSize === 0) {
        console.log(`Baseline image count: ${baselineSize}`);
        console.log(`Target image count: ${targetSize}`);
        console.log('C1: Empty Collection. No images found for one or both periods.');
        console.log('A: Yes');
        console.log('B: No');
        console.log('C1: Empty Collection');
        console.log('C2: No Valid Pixels');
        console.log('C3: Calculation Failure');
        console.log('D: Error');
        return;
    }

    // 4. Processing and Calculation
    // Create a single image representing the mean for each period.
    const baselineImage = baselineColl.mean();
    const targetImage = targetColl.mean();

    // Reducer to get the mean value at the point. Scale is nominal for OISST (0.25 deg).
    const reducer = ee.Reducer.mean();
    const scale = 1000; // Use a reasonable scale to ensure a value is returned.

    const baselineSSTDict = baselineImage.reduceRegion({
        reducer: reducer,
        geometry: location,
        scale: scale,
        maxPixels: 1e9
    });

    const targetSSTDict = targetImage.reduceRegion({
        reducer: reducer,
        geometry: location,
        scale: scale,
        maxPixels: 1e9
    });

    // Asynchronously get info
    const baselineSSTInfo = baselineSSTDict.get('sst').getInfo();
    const targetSSTInfo = targetSSTDict.get('sst').getInfo();

    // 5. Validation & Final Answer
    if (baselineSSTInfo === null || targetSSTInfo === null) {
        console.log(`Baseline SST Raw: ${baselineSSTInfo}`);
        console.log(`Target SST Raw: ${targetSSTInfo}`);
        console.log('C2: No Valid Pixels. The location is likely on land or in a data gap.');
        console.log('A: Yes');
        console.log('B: No');
        console.log('C1: Empty Collection');
        console.log('C2: No Valid Pixels');
        console.log('C3: Calculation Failure');
        console.log('D: Error');
        return;
    }

    // The SST data is in Celsius * 100. Convert it back.
    const baselineTempC = baselineSSTInfo * 0.01;
    const targetTempC = targetSSTInfo * 0.01;

    // Check for calculation failure (e.g., unrealistic temperatures)
    if (baselineTempC < -5 || baselineTempC > 40 || targetTempC < -5 || targetTempC > 40) {
        console.log(`Baseline Temp (°C): ${baselineTempC.toFixed(2)}`);
        console.log(`Target Temp (°C): ${targetTempC.toFixed(2)}`);
        console.log('C3: Calculation Failure. Unrealistic temperature value calculated.');
        console.log('A: Yes');
        console.log('B: No');
        console.log('C1: Empty Collection');
        console.log('C2: No Valid Pixels');
        console.log('C3: Calculation Failure');
        console.log('D: Error');
        return;
    }

    const tempDifference = Math.abs(targetTempC - baselineTempC);

    console.log(`Baseline Period (2003-2014) Avg SST: ${baselineTempC.toFixed(2)}°C`);
    console.log(`Target Period (Mar 2022) Avg SST: ${targetTempC.toFixed(2)}°C`);
    console.log(`Temperature Difference: ${tempDifference.toFixed(2)}°C`);

    if (tempDifference > 1.0) {
        console.log('A: Yes');
    } else {
        console.log('B: No');
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(err => {
    console.error(err);
    console.log('D: Error');
});
